import { forwardRef } from 'react'
import type { TamaguiElement } from 'tamagui'
import { useControllableState } from '../../hooks/useControllableState'
import { Calendar } from '../calendar/Calendar'
import type { DateRange } from '../calendar/dates'
import type { DatePickerProps } from '../date-picker/DatePicker'
import { PickerTrigger } from '../date-picker/PickerTrigger'
import { Popover } from '../popover/Popover'

export interface DateRangePickerProps extends Omit<
  DatePickerProps,
  'value' | 'defaultValue' | 'onValueChange'
> {
  value?: DateRange
  defaultValue?: DateRange
  onValueChange?: (value: DateRange) => void
}

const emptyRange: DateRange = { start: null, end: null }

/**
 * A field that opens a range Calendar: the first press picks the start, the
 * second the end, and then the panel closes.
 */
export const DateRangePicker = forwardRef<TamaguiElement, DateRangePickerProps>(
  function DateRangePicker(
    {
      value,
      defaultValue = emptyRange,
      onValueChange,
      open,
      defaultOpen = false,
      onOpenChange,
      placeholder = 'Pick dates',
      formatOptions = { dateStyle: 'medium' },
      title = 'Choose dates',
      min,
      max,
      isDateDisabled,
      weekStartsOn,
      locale,
      today,
      ...triggerProps
    },
    ref,
  ) {
    const [range, setRange] = useControllableState({
      value,
      defaultValue,
      onChange: onValueChange,
    })
    const [isOpen, setOpen] = useControllableState({
      value: open,
      defaultValue: defaultOpen,
      onChange: onOpenChange,
    })
    const format = new Intl.DateTimeFormat(locale, formatOptions)
    const text = range.start
      ? range.end
        ? // Hermes may lack formatRange.
          typeof format.formatRange === 'function'
          ? format.formatRange(range.start, range.end)
          : `${format.format(range.start)} – ${format.format(range.end)}`
        : `${format.format(range.start)} –`
      : null

    return (
      <Popover open={isOpen} onOpenChange={setOpen} align="start">
        <Popover.Trigger asChild>
          <PickerTrigger ref={ref} valueText={text} placeholder={placeholder} {...triggerProps} />
        </Popover.Trigger>
        <Popover.Content width="auto">
          <Popover.Title>{title}</Popover.Title>
          <Calendar
            alignSelf="center"
            mode="range"
            value={range}
            onValueChange={(next) => {
              setRange(next)
              if (next.start && next.end) setOpen(false)
            }}
            {...{ min, max, isDateDisabled, locale, today }}
            {...(weekStartsOn !== undefined && { weekStartsOn })}
          />
        </Popover.Content>
      </Popover>
    )
  },
)

import { CalendarIcon, IconDefaults } from '@advui/icons'
import { type ReactNode, forwardRef, useId } from 'react'
import { type GetProps, type TamaguiElement, View, isWeb, styled } from 'tamagui'
import { useFieldControl } from '../../hooks/useFieldControl'
import { fieldBoxStyle } from '../input/Input'
import { Text } from '../typography/Text'

const TriggerFrame = styled(View, {
  name: 'PickerTrigger',
  role: 'button',
  render: 'button',
  tabIndex: 0,
  ...fieldBoxStyle,
  flexDirection: 'row',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: '$2',
  cursor: 'pointer',

  variants: {
    size: {
      sm: { height: '$8', paddingHorizontal: '$2.5' },
      md: { height: '$10', paddingHorizontal: '$3' },
      lg: { height: '$12', paddingHorizontal: '$4' },
    },
    invalid: {
      true: { borderColor: '$error', hoverStyle: { borderColor: '$error' } },
    },
    disabled: {
      true: { opacity: 0.5, cursor: 'not-allowed', pointerEvents: 'none' },
    },
  } as const,

  defaultVariants: { size: 'md' },
})

export interface PickerTriggerProps extends Omit<GetProps<typeof TriggerFrame>, 'children'> {
  /** The formatted value, or null to show the placeholder. */
  valueText: string | null
  placeholder: string
  icon?: ReactNode
  'aria-describedby'?: string
}

/**
 * The field-shaped button of Date Picker and Date Range Picker. Its value text
 * is linked with `aria-describedby`, so a label from a Field (which names
 * the button) and the value are both announced.
 */
export const PickerTrigger = forwardRef<TamaguiElement, PickerTriggerProps>(
  function PickerTrigger(triggerProps, ref) {
    const {
      valueText,
      placeholder,
      icon = <CalendarIcon />,
      invalid = false,
      disabled = false,
      'aria-describedby': describedBy,
      ...props
    } = useFieldControl(triggerProps)
    const valueId = useId()
    return (
      <TriggerFrame
        ref={ref}
        invalid={invalid}
        disabled={disabled}
        aria-haspopup="dialog"
        aria-invalid={invalid || undefined}
        aria-disabled={disabled || undefined}
        aria-describedby={[valueId, describedBy].filter(Boolean).join(' ')}
        {...(isWeb
          ? { type: 'button' }
          : // Native has no aria-describedby; expose the date as the value.
            { accessibilityValue: { text: valueText ?? placeholder } })}
        {...props}
      >
        <Text
          id={valueId}
          size="sm"
          numberOfLines={1}
          flexShrink={1}
          color={valueText ? '$foreground' : '$placeholderColor'}
        >
          {valueText ?? placeholder}
        </Text>
        <IconDefaults size={16} color="$mutedForeground">
          {icon}
        </IconDefaults>
      </TriggerFrame>
    )
  },
)

import { ChevronLeftIcon, ChevronRightIcon } from '@advui/icons'
import { forwardRef, useEffect, useId, useMemo, useRef, useState } from 'react'
import { type GetProps, type TamaguiElement, View, XStack, isWeb, styled } from 'tamagui'
import { useControllableState } from '../../hooks/useControllableState'
import { IconButton } from '../icon-button/IconButton'
import { Text } from '../typography/Text'
import {
  type DateRange,
  addDays,
  addMonths,
  clampDay,
  compareDays,
  isSameDay,
  isSameMonth,
  monthGrid,
  startOfDay,
  toISODate,
} from './dates'

const CalendarFrame = styled(View, {
  name: 'Calendar',
  gap: '$3',
  alignSelf: 'flex-start',
})

const DayCell = styled(View, {
  name: 'CalendarDay',
  width: '$9',
  height: '$9',
  alignItems: 'center',
  justifyContent: 'center',
  borderRadius: '$md',
  cursor: 'pointer',
  hoverStyle: { backgroundColor: '$muted' },
  focusVisibleStyle: {
    outlineColor: '$ring',
    outlineStyle: 'solid',
    outlineWidth: 2,
    outlineOffset: 1,
  },

  variants: {
    selection: {
      none: {},
      // Ends of a range and the single selected day.
      end: {
        backgroundColor: '$primary',
        hoverStyle: { backgroundColor: '$primary' },
      },
      middle: {
        backgroundColor: '$accent',
        borderRadius: 0,
        hoverStyle: { backgroundColor: '$accent' },
      },
    },
    disabled: {
      true: { opacity: 0.4, cursor: 'not-allowed', hoverStyle: { backgroundColor: 'transparent' } },
    },
  } as const,

  defaultVariants: { selection: 'none' },
})

type SingleProps = {
  mode?: 'single'
  value?: Date | null
  defaultValue?: Date | null
  onValueChange?: (value: Date | null) => void
}

type RangeProps = {
  mode: 'range'
  value?: DateRange
  defaultValue?: DateRange
  onValueChange?: (value: DateRange) => void
}

type FrameProps = Omit<GetProps<typeof CalendarFrame>, 'children' | 'defaultValue'>

export type CalendarProps = FrameProps &
  (SingleProps | RangeProps) & {
    /** First day of the visible month (controlled). */
    month?: Date
    defaultMonth?: Date
    onMonthChange?: (month: Date) => void
    /** Earliest selectable day. */
    min?: Date
    /** Latest selectable day. */
    max?: Date
    /** Return true to make a day unselectable (weekends, booked days…). */
    isDateDisabled?: (date: Date) => boolean
    /** 0 = Sunday, 1 = Monday… Default 0. */
    weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6
    /** BCP 47 locale for month and day names. Defaults to the device locale. */
    locale?: string
    /** Override "today" (tests, screenshots). */
    today?: Date
    /** Accessible names of the month buttons. */
    previousMonthLabel?: string
    nextMonthLabel?: string
  }

const emptyRange: DateRange = { start: null, end: null }

/**
 * A month grid for picking a day or a range. On web it follows the WAI-ARIA
 * grid pattern: one Tab stop, arrow keys between days, Page Up / Page Down
 * between months. On native every day is a labelled button.
 */
export const Calendar = forwardRef<TamaguiElement, CalendarProps>(function Calendar(props, ref) {
  const {
    mode = 'single',
    value: valueProp,
    defaultValue,
    onValueChange,
    month: monthProp,
    defaultMonth,
    onMonthChange,
    min,
    max,
    isDateDisabled,
    weekStartsOn = 0,
    locale,
    today: todayProp,
    previousMonthLabel = 'Previous month',
    nextMonthLabel = 'Next month',
    ...frameProps
  } = props
  const today = startOfDay(todayProp ?? new Date())

  // Both modes share one state; single mode stores its day as the range start.
  const toRange = (v: Date | DateRange | null | undefined): DateRange | undefined =>
    v === undefined ? undefined : v instanceof Date || v === null ? { start: v, end: null } : v
  const [range, setRange] = useControllableState<DateRange>({
    value: toRange(valueProp),
    defaultValue: toRange(defaultValue) ?? emptyRange,
    onChange: (next) =>
      mode === 'range'
        ? (onValueChange as RangeProps['onValueChange'])?.(next)
        : (onValueChange as SingleProps['onValueChange'])?.(next.start),
  })

  const initialDay = range.start ?? clampDay(today, min, max)
  const [month, setMonth] = useControllableState({
    value: monthProp,
    defaultValue: new Date(
      (defaultMonth ?? initialDay).getFullYear(),
      (defaultMonth ?? initialDay).getMonth(),
      1,
    ),
    onChange: onMonthChange,
  })
  const [focusedDay, setFocusedDay] = useState(initialDay)
  const pendingFocus = useRef(false)
  const dayRefs = useRef(new Map<string, HTMLElement>())
  const captionId = useId()

  const formats = useMemo(
    () => ({
      caption: new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }),
      day: new Intl.DateTimeFormat(locale, {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
      }),
      weekdayShort: new Intl.DateTimeFormat(locale, { weekday: 'short' }),
      weekdayLong: new Intl.DateTimeFormat(locale, { weekday: 'long' }),
    }),
    [locale],
  )

  const weeks = monthGrid(month, weekStartsOn)
  const isDisabled = (day: Date) =>
    (min != null && compareDays(day, min) < 0) ||
    (max != null && compareDays(day, max) > 0) ||
    !!isDateDisabled?.(day)
  // The one day that takes Tab focus: the focused day if it is in view.
  const tabDay = isSameMonth(focusedDay, month) ? focusedDay : month

  useEffect(() => {
    if (!pendingFocus.current) return
    pendingFocus.current = false
    dayRefs.current.get(toISODate(focusedDay))?.focus()
  }, [focusedDay, month])

  const showMonth = (next: Date) => setMonth(new Date(next.getFullYear(), next.getMonth(), 1))
  const canGoBack = !min || compareDays(addDays(month, -1), min) >= 0
  const canGoForward = !max || compareDays(addMonths(month, 1), max) <= 0

  const select = (day: Date) => {
    if (isDisabled(day)) return
    setFocusedDay(day)
    if (mode === 'single') return setRange({ start: day, end: null })
    const { start, end } = range
    if (!start || end || compareDays(day, start) < 0) setRange({ start: day, end: null })
    else setRange({ start, end: day })
  }

  const moveFocus = (day: Date) => {
    const next = clampDay(day, min, max)
    pendingFocus.current = true
    setFocusedDay(next)
    if (!isSameMonth(next, month)) showMonth(next)
  }

  type DayKeyEvent = { key: string; shiftKey: boolean; preventDefault: () => void }
  const onDayKeyDown = (day: Date, event: DayKeyEvent) => {
    const offset = (day.getDay() - weekStartsOn + 7) % 7
    const moves: Record<string, () => Date> = {
      ArrowLeft: () => addDays(day, -1),
      ArrowRight: () => addDays(day, 1),
      ArrowUp: () => addDays(day, -7),
      ArrowDown: () => addDays(day, 7),
      Home: () => addDays(day, -offset),
      End: () => addDays(day, 6 - offset),
      PageUp: () => addMonths(day, event.shiftKey ? -12 : -1),
      PageDown: () => addMonths(day, event.shiftKey ? 12 : 1),
    }
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      select(day)
    } else if (moves[event.key]) {
      event.preventDefault()
      moveFocus(moves[event.key]!())
    }
  }

  const selectionOf = (day: Date) => {
    const { start, end } = range
    if (isSameDay(day, start) || isSameDay(day, end)) return 'end' as const
    if (start && end && compareDays(day, start) > 0 && compareDays(day, end) < 0)
      return 'middle' as const
    return 'none' as const
  }

  return (
    <CalendarFrame ref={ref} {...frameProps}>
      <XStack alignItems="center" justifyContent="space-between">
        <IconButton
          size="sm"
          variant="ghost"
          icon={<ChevronLeftIcon />}
          aria-label={previousMonthLabel}
          disabled={!canGoBack}
          onPress={() => showMonth(addMonths(month, -1))}
        />
        <Text id={captionId} size="sm" weight="semibold" aria-live="polite">
          {formats.caption.format(month)}
        </Text>
        <IconButton
          size="sm"
          variant="ghost"
          icon={<ChevronRightIcon />}
          aria-label={nextMonthLabel}
          disabled={!canGoForward}
          onPress={() => showMonth(addMonths(month, 1))}
        />
      </XStack>

      <View role={isWeb ? 'grid' : undefined} aria-labelledby={captionId} gap="$1">
        <XStack role={isWeb ? 'row' : undefined}>
          {weeks[0]!.map((day) => (
            <View
              key={day.getDay()}
              role={isWeb ? 'columnheader' : undefined}
              aria-label={formats.weekdayLong.format(day)}
              width="$9"
              alignItems="center"
            >
              <Text size="xs" tone="muted" aria-hidden>
                {formats.weekdayShort.format(day)}
              </Text>
            </View>
          ))}
        </XStack>
        {weeks.map((week) => (
          <XStack key={toISODate(week[0]!)} role={isWeb ? 'row' : undefined}>
            {week.map((day) => {
              const iso = toISODate(day)
              if (!isSameMonth(day, month)) {
                return (
                  <View
                    key={iso}
                    role={(isWeb ? 'gridcell' : undefined) as never}
                    width="$9"
                    height="$9"
                  />
                )
              }
              const selection = selectionOf(day)
              const selected = selection !== 'none'
              const disabled = isDisabled(day)
              const isToday = isSameDay(day, today)
              return (
                <DayCell
                  key={iso}
                  ref={(node: TamaguiElement | null) => {
                    if (node) dayRefs.current.set(iso, node as unknown as HTMLElement)
                    else dayRefs.current.delete(iso)
                  }}
                  selection={selection}
                  disabled={disabled}
                  role={(isWeb ? 'gridcell' : 'button') as never}
                  // Native views with a role need `accessible` to be announced.
                  {...(!isWeb && { accessible: true })}
                  aria-label={formats.day.format(day)}
                  aria-selected={selected}
                  aria-disabled={disabled || undefined}
                  aria-current={isToday ? 'date' : undefined}
                  {...(isWeb && {
                    tabIndex: isSameDay(day, tabDay) ? 0 : -1,
                    onKeyDown: (event: DayKeyEvent) => onDayKeyDown(day, event),
                    onFocus: () => setFocusedDay(day),
                  })}
                  onPress={() => select(day)}
                >
                  <Text
                    size="sm"
                    {...(isToday && { weight: 'semibold' as const })}
                    color={
                      selection === 'end'
                        ? '$primaryForeground'
                        : selection === 'middle'
                          ? '$accentForeground'
                          : isToday
                            ? '$primaryText'
                            : '$foreground'
                    }
                  >
                    {day.getDate()}
                  </Text>
                </DayCell>
              )
            })}
          </XStack>
        ))}
      </View>
    </CalendarFrame>
  )
})

// Calendar-day helpers. Dates are local calendar days: the time part is
// ignored, so a picked day never shifts with time zones.

export interface DateRange {
  start: Date | null
  end: Date | null
}

export function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function addDays(date: Date, days: number) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days)
}

/** Same day of the month, clamped to the target month's length (31 Jan + 1 → 28/29 Feb). */
export function addMonths(date: Date, months: number) {
  const first = new Date(date.getFullYear(), date.getMonth() + months, 1)
  const last = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()
  return new Date(first.getFullYear(), first.getMonth(), Math.min(date.getDate(), last))
}

export function isSameDay(a: Date | null | undefined, b: Date | null | undefined) {
  return (
    !!a &&
    !!b &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  )
}

export function isSameMonth(a: Date, b: Date) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

export function compareDays(a: Date, b: Date) {
  return startOfDay(a).getTime() - startOfDay(b).getTime()
}

export function clampDay(date: Date, min?: Date, max?: Date) {
  if (min && compareDays(date, min) < 0) return startOfDay(min)
  if (max && compareDays(date, max) > 0) return startOfDay(max)
  return startOfDay(date)
}

/** Six rows of seven days covering `month`, starting on `weekStartsOn`. */
export function monthGrid(month: Date, weekStartsOn: number) {
  const first = new Date(month.getFullYear(), month.getMonth(), 1)
  const start = addDays(first, -((first.getDay() - weekStartsOn + 7) % 7))
  return Array.from({ length: 6 }, (_, row) =>
    Array.from({ length: 7 }, (_, col) => addDays(start, row * 7 + col)),
  )
}

/** ISO date without time zones: `2026-09-28`. */
export function toISODate(date: Date) {
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

